using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

namespace NightLens {
public class CatalogInfo {
    public string Key,Path,Error=""; public int Rows,Skipped; public List<Target> Targets=new List<Target>();
    public override string ToString(){return System.IO.Path.GetFileNameWithoutExtension(Key)+" — "+Targets.Count.ToString("N0")+" targets"+(Skipped>0?" ("+Skipped+" unplannable records)":"")+(Error!=""?" · "+Error:"");}
}
public static class CatalogLibrary {
    public static string BuiltIn=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Catalogs");
    public static string Imported {get{return Path.Combine(Settings.Folder,"Catalogs");}}
    static Dictionary<string,Tuple<long,DateTime,CatalogInfo>> cache=new Dictionary<string,Tuple<long,DateTime,CatalogInfo>>();
    public static List<CatalogInfo> Available(){var files=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string dir in new[]{BuiltIn,Imported})if(Directory.Exists(dir))foreach(string path in Directory.GetFiles(dir,"*.csv"))files[Path.GetFileName(path)]=path;return files.OrderBy(x=>x.Key=="Messier.csv"?"0":x.Key).Select(x=>Read(x.Value)).ToList();}
    public static CatalogInfo Read(string path){var fi=new FileInfo(path);Tuple<long,DateTime,CatalogInfo> old;if(cache.TryGetValue(path,out old)&&old.Item1==fi.Length&&old.Item2==fi.LastWriteTimeUtc)return old.Item3;var result=Parse(File.ReadAllText(path),Path.GetFileName(path));result.Path=path;cache[path]=Tuple.Create(fi.Length,fi.LastWriteTimeUtc,result);return result;}
    static double Number(string value){double n;if(!double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new FormatException();return n;}
    static double Sex(string value){var parts=value.Trim().TrimStart('+','-').Split(':');if(parts.Length!=3)throw new FormatException();double sign=value.Trim().StartsWith("-")?-1:1;double d=Number(parts[0]),m=Number(parts[1]),s=Number(parts[2]);if(m<0||m>=60||s<0||s>=60)throw new FormatException();return sign*(d+m/60+s/3600);}
    static string TypeName(string code){var codes=new Dictionary<string,string>{{"G","Galaxy"},{"GPair","Galaxy pair"},{"GTrpl","Galaxy triplet"},{"GGroup","Galaxy group"},{"OCl","Open cluster"},{"GCl","Globular cluster"},{"Cl+N","Cluster and nebula"},{"PN","Planetary nebula"},{"HII","Emission nebula"},{"EmN","Emission nebula"},{"DrkN","Dark nebula"},{"RfN","Reflection nebula"},{"Neb","Nebula"},{"SNR","Supernova remnant"},{"*Ass","Stellar association"},{"*","Star"},{"**","Double star"}};return codes.ContainsKey(code)?codes[code]:code;}
    public static CatalogInfo Parse(string data,string key){var info=new CatalogInfo{Key=key};try{char separator=data.Split('\n')[0].Contains(';')?';':',';var rows=Csv(data,separator);if(rows.Count<2)throw new FormatException("No catalog rows.");var header=rows[0];bool open=header.Contains("RA")&&header.Contains("Dec");string[] needed=open?new[]{"Name","Type","RA","Dec","MajAx","MinAx"}:new[]{"Name","Type","RAHours","DecDegrees","MajorArcmin","MinorArcmin"};foreach(string column in needed)if(!header.Contains(column))throw new FormatException("Missing column: "+column);
        for(int i=1;i<rows.Count;i++){if(rows[i].All(string.IsNullOrWhiteSpace))continue;info.Rows++;var row=rows[i];Func<string,string> get=name=>{int index=Array.IndexOf(header,name);return index>=0&&index<row.Length?row[index].Trim():"";};
            try{string name=get("Name"),type=get("Type");if(type=="NonEx"||type=="Dup"||string.IsNullOrWhiteSpace(name))throw new FormatException();double ra=open?Sex(get("RA")):Number(get("RAHours")),dec=open?Sex(get("Dec")):Number(get("DecDegrees"));if(ra<0||ra>=24||Math.Abs(dec)>90)throw new FormatException();double major=0,minor=0;string size=get(open?"MajAx":"MajorArcmin");if(size!="")major=Number(size);size=get(open?"MinAx":"MinorArcmin");if(size!="")minor=Number(size);if(major<0||minor<0)throw new FormatException();if(minor==0&&major>0)minor=major;
            string band=open?"V":"unspecified";string mag=get(open?"V-Mag":"Magnitude");if(mag==""&&open){mag=get("B-Mag");band="B";}double? magnitude=mag==""?null:(double?)Number(mag);string canonical=open?name:get("CanonicalId");if(canonical=="")canonical=ra.ToString("0.00000",CultureInfo.InvariantCulture)+":"+dec.ToString("0.00000",CultureInfo.InvariantCulture);
            string label=name;if(open&&get("M")!="")label="M"+int.Parse(get("M"))+" · "+name;string common=get("Common names");if(common!="")label=common.Split(',')[0]+" · "+label;
            info.Targets.Add(new Target(label,TypeName(type),ra,dec,major,minor){Canonical=ImagingGroups.Identity(canonical),CatalogName=Path.GetFileNameWithoutExtension(key),Magnitude=magnitude,MagnitudeBand=band,Vmag=ObjectInfo.Number(get("V-Mag")),Bmag=ObjectInfo.Number(get("B-Mag")),Jmag=ObjectInfo.Number(get("J-Mag")),Hmag=ObjectInfo.Number(get("H-Mag")),Kmag=ObjectInfo.Number(get("K-Mag")),SurfaceBrightness=ObjectInfo.Number(get("SurfBr")),Constellation=get("Const"),Morphology=get("Hubble"),CatalogNotes=get("OpenNGC notes"),Aliases=AliasIds(name,canonical,open?get("M"):"",open?get("NGC"):"",open?get("IC"):"",get("Aliases"))});
            }catch{info.Skipped++;}
        }if(info.Targets.Count==0)info.Error="No usable coordinates";
    }catch(Exception e){info.Error=e.Message;}return info;}
    static List<string> AliasIds(string name,string canonical,string messier,string ngc,string ic,string custom){var ids=new List<string>{canonical};if(name.StartsWith("NGC")||name.StartsWith("IC")||name.StartsWith("M"))ids.Add(name);if(messier!="")ids.Add("M"+messier);foreach(string id in ngc.Split(','))if(id.Trim()!="")ids.Add("NGC"+id.Trim());foreach(string id in ic.Split(','))if(id.Trim()!="")ids.Add("IC"+id.Trim());ids.AddRange(custom.Split('|').Where(x=>x.Trim()!=""));return ids.Select(ImagingGroups.Identity).Where(x=>x!="").Distinct(StringComparer.OrdinalIgnoreCase).ToList();}
    public static List<Target> Load(Settings settings,out string notice){var result=new List<Target>();var identities=new Dictionary<string,Target>(StringComparer.OrdinalIgnoreCase);var available=Available();var selected=settings.EnabledCatalogs??new List<string>();var errors=new List<string>();foreach(string key in selected){var catalog=available.FirstOrDefault(x=>x.Key.Equals(key,StringComparison.OrdinalIgnoreCase));if(catalog==null){errors.Add(key+" missing");continue;}if(catalog.Error!="")errors.Add(key+": "+catalog.Error);foreach(var target in catalog.Targets){var matched=target.Aliases.Where(identities.ContainsKey).Select(id=>identities[id]).Distinct().ToList();var keeper=matched.FirstOrDefault();if(keeper==null){keeper=new Target(target.Name,target.Type,target.Ra,target.Dec,target.Major,target.Minor){Canonical=target.Canonical,CatalogName=target.CatalogName,Magnitude=target.Magnitude,Aliases=new List<string>(target.Aliases)};result.Add(keeper);}ObjectInfo.Merge(keeper,target);foreach(var duplicate in matched.Skip(1)){ObjectInfo.Merge(keeper,duplicate);foreach(var id in duplicate.Aliases){identities[id]=keeper;if(!keeper.Aliases.Contains(id))keeper.Aliases.Add(id);}result.Remove(duplicate);}foreach(string id in target.Aliases){identities[id]=keeper;if(!keeper.Aliases.Contains(id))keeper.Aliases.Add(id);}}}notice=string.Join("; ",errors);return result;}
    public static List<string[]> Csv(string text,char delimiter){var rows=new List<string[]>();var row=new List<string>();var value=new StringBuilder();bool quoted=false;for(int i=0;i<text.Length;i++){char c=text[i];if(i==0&&c=='\uFEFF')continue;if(c=='"'){if(quoted&&i+1<text.Length&&text[i+1]=='"'){value.Append('"');i++;}else quoted=!quoted;}else if(c==delimiter&&!quoted){row.Add(value.ToString());value.Clear();}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;row.Add(value.ToString());value.Clear();rows.Add(row.ToArray());row.Clear();}else value.Append(c);}if(quoted)throw new FormatException("Unclosed CSV quote.");if(value.Length>0||row.Count>0){row.Add(value.ToString());rows.Add(row.ToArray());}return rows;}
}
}


